class Solution {

    public Node cloneGraph(Node node) {
        if (node == null) return null;
        Map<Node, Node> copy = new HashMap<>();
        Deque<Node> q = new ArrayDeque<>();
        copy.put(node, new Node(node.val));
        q.add(node);
        // Pass 1: discover every node and create an empty copy
        while (!q.isEmpty()) {
            Node cur = q.poll();
            for (Node nb : cur.neighbors) {
                if (!copy.containsKey(nb)) {
                    copy.put(nb, new Node(nb.val));
                    q.add(nb);
                }
            }
        }
        // Pass 2: wire the neighbour lists of the copies
        for (Map.Entry<Node, Node> e : copy.entrySet()) {
            for (Node nb : e.getKey().neighbors) {
                e.getValue().neighbors.add(copy.get(nb));
            }
        }
        return copy.get(node);
    }
}

