var cloneGraph = function (node) {
    if (node === null) return null;
    const copy = new Map();
    copy.set(node, new Node(node.val));
    const q = [node];
    // Pass 1: discover every node and create an empty copy
    for (let i = 0; i < q.length; i++) {
        for (const nb of q[i].neighbors) {
            if (!copy.has(nb)) {
                copy.set(nb, new Node(nb.val));
                q.push(nb);
            }
        }
    }
    // Pass 2: wire the neighbour lists
    for (const [orig, cl] of copy) {
        for (const nb of orig.neighbors)
            cl.neighbors.push(copy.get(nb));
    }
    return copy.get(node);
};

