var cloneGraph = function (node) {
    const copies = new Map();
    const dfs = (cur) => {
        if (cur === null) return null;
        if (copies.has(cur)) return copies.get(cur);
        const clone = new Node(cur.val);
        copies.set(cur, clone); // register first: breaks cycles
        for (const nb of cur.neighbors) clone.neighbors.push(dfs(nb));
        return clone;
    };
    return dfs(node);
};

