class Solution {

    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) adj.add(new ArrayList<>());
        for (int[] p : prerequisites) adj.get(p[1]).add(p[0]);
        for (int s = 0; s < numCourses; s++) {
            int[] state = new int[numCourses]; // fresh for every start (the "brute" part)
            if (hasCycle(s, adj, state)) return false;
        }
        return true;
    }

    private boolean hasCycle(
        int u,
        List<List<Integer>> adj,
        int[] state
    ) {
        state[u] = 1; // on current path
        for (int v : adj.get(u)) {
            if (state[v] == 1) return true; // back edge -> cycle
            if (state[v] == 0 && hasCycle(v, adj, state)) return true;
        }
        state[u] = 2; // finished
        return false;
    }
}

