        for (const v of adj[u]) {
            if (state[v] === 1) return true;
            if (state[v] === 0 && hasCycle(v, state)) return true;
        }
        state[u] = 2;
        return false;
    };
    for (let s = 0; s < numCourses; s++) {
        if (hasCycle(s, new Array(numCourses).fill(0))) return false;
    }
    return true;
};

