class Solution {

    public int[] findOrder(int numCourses, int[][] prerequisites) {
        List<List<Integer>> pre = new ArrayList<>(); // pre.get(a) = courses needed before a
        for (int i = 0; i < numCourses; i++) pre.add(new ArrayList<>());
        for (int[] p : prerequisites) pre.get(p[0]).add(p[1]);
        boolean[] taken = new boolean[numCourses];
        int[] order = new int[numCourses];
        int idx = 0;
        while (idx < numCourses) {
            boolean progress = false;
            for (int c = 0; c < numCourses; c++) {
                if (taken[c]) continue;
                boolean ready = true;
                for (int need : pre.get(c))
                    if (!taken[need]) {
                        ready = false;
                        break;
                    }
                if (ready) {
                    taken[c] = true;
                    order[idx++] = c;
                    progress = true;
                }
            }
            if (!progress) return new int[0]; // stuck -> cycle
        }
        return order;
    }
}

