        for (let c = 0; c < numCourses; c++) {
            if (taken[c]) continue;
            if (pre[c].every((need) => taken[need])) {
                taken[c] = true;
                order.push(c);
                progress = true;
            }
        }
        if (!progress) return []; // stuck -> cycle
    }
    return order;
};

