var validTree = function (n, edges) {
    if (edges.length !== n - 1) return false;
    const adj = Array.from({ length: n }, () => []);
    const reachable = (src, dst) => {
        const seen = new Array(n).fill(false);
        const q = [src];
        seen[src] = true;
        for (let i = 0; i < q.length; i++) {
            if (q[i] === dst) return true;
            for (const v of adj[q[i]])
                if (!seen[v]) {
                    seen[v] = true;
                    q.push(v);
                }
        }
        return false;
    };
    for (const [u, v] of edges) {
        if (reachable(u, v)) return false; // already connected -> cycle
        adj[u].push(v);
        adj[v].push(u);
    }
    return true;
};

