class Solution {

    private int[] parent, size;

    public boolean validTree(int n, int[][] edges) {
        if (edges.length != n - 1) return false; // a tree has exactly n-1 edges
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        for (int[] e : edges) {
            int a = find(e[0]),
                b = find(e[1]);
            if (a == b) return false; // edge inside one component -> cycle

            if (size[a] < size[b]) {
                int t = a;
                a = b;
                b = t;
            }
            parent[b] = a; // union by size
            size[a] += size[b];
        }
        return true; // n-1 edges + no cycle => connected
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]]; // path halving
            x = parent[x];
        }
        return x;
    }
}

