class Solution {

    public int maxAreaOfIsland(int[][] grid) {
        int m = grid.length,
            n = grid[0].length,
            best = 0;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) continue;
                boolean[][] seen = new boolean[m][n]; // fresh every time: the wasteful part
                Deque<int[]> q = new ArrayDeque<>();
                q.add(new int[] { r, c });
                seen[r][c] = true;
                int area = 0;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    area++;
                    for (int[] d : dirs) {
                        int nr = cur[0] + d[0],
                            nc = cur[1] + d[1];
                        if (
                            nr >= 0 &&
                            nr < m &&
                            nc >= 0 &&
                            nc < n &&
                            grid[nr][nc] == 1 &&
                            !seen[nr][nc]
                        ) {
                            seen[nr][nc] = true;
                            q.add(new int[] { nr, nc });
                        }
                    }
                }
                best = Math.max(best, area);
            }
        }
        return best;
    }
}

