class Solution {

    public int numIslands(char[][] grid) {
        int m = grid.length,
            n = grid[0].length,
            count = 0;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] != '1') continue;
                boolean[][] seen = new boolean[m][n];
                Deque<int[]> q = new ArrayDeque<>();
                q.add(new int[] { r, c });
                seen[r][c] = true;
                int minId = r * n + c;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    minId = Math.min(minId, cur[0] * n + cur[1]);
                    for (int[] d : dirs) {
                        int nr = cur[0] + d[0],
                            nc = cur[1] + d[1];
                        if (
                            nr >= 0 &&
                            nr < m &&
                            nc >= 0 &&
                            nc < n &&
                            grid[nr][nc] == '1' &&
                            !seen[nr][nc]
                        ) {
                            seen[nr][nc] = true;
                            q.add(new int[] { nr, nc });
                        }
                    }
                }
                if (minId == r * n + c) count++; // this cell represents its island
            }
        }
        return count;
    }
}

