class Solution {

    public int numIslands(char[][] grid) {
        int count = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '1') {
                    count++; // new island discovered
                    sink(grid, r, c); // erase it so it isn't counted again
                }
            }
        }
        return count;
    }

    private void sink(char[][] g, int r, int c) {
        if (
            r < 0 ||
            r >= g.length ||
            c < 0 ||
            c >= g[0].length ||
            g[r][c] != '1'
        ) return;
        g[r][c] = '0';
        sink(g, r + 1, c);
        sink(g, r - 1, c);
        sink(g, r, c + 1);
        sink(g, r, c - 1);
    }
}

