class Solution {

    private int m, n;
    private boolean pac, atl;

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        m = heights.length;
        n = heights[0].length;
        List<List<Integer>> res = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                pac = false;
                atl = false;
                flow(heights, r, c, new boolean[m][n]); // fresh search per cell
                if (pac && atl) res.add(Arrays.asList(r, c));
            }
        }
        return res;
    }

    private void flow(int[][] h, int r, int c, boolean[][] seen) {
        seen[r][c] = true;
        if (r == 0 || c == 0) pac = true;
        if (r == m - 1 || c == n - 1) atl = true;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        for (int[] d : dirs) {
            int nr = r + d[0],
                nc = c + d[1];
            if (
                nr >= 0 &&
                nr < m &&
                nc >= 0 &&
                nc < n &&
                !seen[nr][nc] &&
                h[nr][nc] <= h[r][c]
            ) {
                flow(h, nr, nc, seen); // water moves downhill
            }
        }
    }
}

