class Solution {

    private int m, n;
    private int[][] h;

    public List<List<Integer>> pacificAtlantic(int[][] heights) {
        h = heights;
        m = h.length;
        n = h[0].length;
        boolean[][] pac = new boolean[m][n],
            atl = new boolean[m][n];
        for (int r = 0; r < m; r++) {
            climb(r, 0, pac); // left edge -> Pacific
            climb(r, n - 1, atl); // right edge -> Atlantic
        }
        for (int c = 0; c < n; c++) {
            climb(0, c, pac); // top edge -> Pacific
            climb(m - 1, c, atl); // bottom edge -> Atlantic
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) if (
            pac[r][c] && atl[r][c]
        ) res.add(Arrays.asList(r, c));
        return res;
    }

    private void climb(int r, int c, boolean[][] ocean) {
        if (ocean[r][c]) return;
        ocean[r][c] = true;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        for (int[] d : dirs) {
            int nr = r + d[0],
                nc = c + d[1];
            if (
                nr >= 0 &&
                nr < m &&
                nc >= 0 &&
                nc < n &&
                h[nr][nc] >= h[r][c]
            ) {
                climb(nr, nc, ocean); // neighbour is higher or equal: water could flow from it to here
            }
        }
    }
}

