class Solution {

    public int[] findRedundantConnection(int[][] edges) {
        int n = edges.length;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            if (
                connected(e[0], e[1], adj, new boolean[n + 1])
            ) return e; // closes the cycle
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        return new int[0];
    }

    private boolean connected(
        int u,
        int target,
        List<List<Integer>> adj,
        boolean[] seen
    ) {
        if (u == target) return true;
        seen[u] = true;
        for (int v : adj.get(u))
            if (
                !seen[v] && connected(v, target, adj, seen)
            ) return true;
        return false;
    }
}

