    const adj = Array.from({ length: n + 1 }, () => []);
    const connected = (u, target, seen) => {
        if (u === target) return true;
        seen[u] = true;
        for (const v of adj[u])
            if (!seen[v] && connected(v, target, seen)) return true;
        return false;
    };
    for (const [u, v] of edges) {
        if (connected(u, v, new Array(n + 1).fill(false)))
            return [u, v];
        adj[u].push(v);
        adj[v].push(u);
    }
    return [];
};

