class Solution {

    public int orangesRotting(int[][] grid) {
        int m = grid.length,
            n = grid[0].length,
            minutes = 0;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        while (true) {
            List<int[]> toRot = new ArrayList<>();
            for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) if (
                grid[r][c] == 1
            ) for (int[] d : dirs) {
                int nr = r + d[0],
                    nc = c + d[1];
                if (
                    nr >= 0 &&
                    nr < m &&
                    nc >= 0 &&
                    nc < n &&
                    grid[nr][nc] == 2
                ) {
                    toRot.add(new int[] { r, c });
                    break;
                }
            }
            if (toRot.isEmpty()) break;
            for (int[] p : toRot) grid[p[0]][p[1]] = 2; // rot simultaneously

            minutes++;
        }
        for (int[] row : grid) for (int x : row) if (x == 1) return -1;
        return minutes;
    }
}

