class Solution {

    public int orangesRotting(int[][] grid) {
        int m = grid.length,
            n = grid[0].length,
            fresh = 0;
        Deque<int[]> q = new ArrayDeque<>();
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) {
            if (grid[r][c] == 2) q.add(new int[] { r, c });
            // all sources at minute 0
            else if (grid[r][c] == 1) fresh++;
        }
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        int minutes = 0;
        while (!q.isEmpty() && fresh > 0) {
            for (int sz = q.size(); sz > 0; sz--) {
                // one level = one minute
                int[] cur = q.poll();
                for (int[] d : dirs) {
                    int nr = cur[0] + d[0],
                        nc = cur[1] + d[1];
                    if (
                        nr >= 0 &&
                        nr < m &&
                        nc >= 0 &&
                        nc < n &&
                        grid[nr][nc] == 1
                    ) {
                        grid[nr][nc] = 2; // mark when enqueuing
                        fresh--;

                        q.add(new int[] { nr, nc });
                    }
                }
            }
            minutes++;
        }
        return fresh == 0 ? minutes : -1;
    }
}

