class Solution {

    public void solve(char[][] board) {
        int m = board.length,
            n = board[0].length;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        List<int[]> flip = new ArrayList<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] != 'O') continue;
                boolean[][] seen = new boolean[m][n];
                Deque<int[]> q = new ArrayDeque<>();
                q.add(new int[] { r, c });
                seen[r][c] = true;
                boolean touchesBorder = false;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    if (
                        cur[0] == 0 ||
                        cur[1] == 0 ||
                        cur[0] == m - 1 ||
                        cur[1] == n - 1
                    ) touchesBorder = true;
                    for (int[] d : dirs) {
                        int nr = cur[0] + d[0],
                            nc = cur[1] + d[1];
                        if (
                            nr >= 0 &&
                            nr < m &&
                            nc >= 0 &&
                            nc < n &&
                            board[nr][nc] == 'O' &&
                            !seen[nr][nc]
                        ) {
                            seen[nr][nc] = true;
                            q.add(new int[] { nr, nc });
                        }
                    }
                }
                if (!touchesBorder) flip.add(new int[] { r, c });
            }
        }
        for (int[] p : flip) board[p[0]][p[1]] = 'X';
    }
}

