class Solution {

    public void solve(char[][] board) {
        int m = board.length,
            n = board[0].length;
        for (int r = 0; r < m; r++) {
            mark(board, r, 0);
            mark(board, r, n - 1);
        }
        for (int c = 0; c < n; c++) {
            mark(board, 0, c);
            mark(board, m - 1, c);
        }
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) {
            if (board[r][c] == 'O') board[r][c] = 'X';
            // not reachable from border: captured
            else if (board[r][c] == '#') board[r][c] = 'O'; // safe: restore
        }
    }

    private void mark(char[][] b, int r, int c) {
        if (
            r < 0 ||
            r >= b.length ||
            c < 0 ||
            c >= b[0].length ||
            b[r][c] != 'O'
        ) return;
        b[r][c] = '#';
        mark(b, r + 1, c);
        mark(b, r - 1, c);
        mark(b, r, c + 1);
        mark(b, r, c - 1);
    }
}

