class Solution {

    public void wallsAndGates(int[][] rooms) {
        int m = rooms.length,
            n = rooms[0].length;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (rooms[r][c] != 0) continue; // start a BFS from each gate
                boolean[][] seen = new boolean[m][n];
                Deque<int[]> q = new ArrayDeque<>();
                q.add(new int[] { r, c, 0 });
                seen[r][c] = true;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    for (int[] d : dirs) {
                        int nr = cur[0] + d[0],
                            nc = cur[1] + d[1];
                        if (
                            nr >= 0 &&
                            nr < m &&
                            nc >= 0 &&
                            nc < n &&
                            !seen[nr][nc] &&
                            rooms[nr][nc] > 0
                        ) {
                            seen[nr][nc] = true;

                            rooms[nr][nc] = Math.min(
                                rooms[nr][nc],
                                cur[2] + 1
                            );
                            q.add(new int[] { nr, nc, cur[2] + 1 });
                        }
                    }
                }
            }
        }
    }
}

