class Solution {

    private static final int INF = Integer.MAX_VALUE;

    public void wallsAndGates(int[][] rooms) {
        int m = rooms.length,
            n = rooms[0].length;
        Deque<int[]> q = new ArrayDeque<>();
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) if (
            rooms[r][c] == 0
        ) q.add(new int[] { r, c }); // all gates are sources
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] d : dirs) {
                int nr = cur[0] + d[0],
                    nc = cur[1] + d[1];
                if (
                    nr >= 0 &&
                    nr < m &&
                    nc >= 0 &&
                    nc < n &&
                    rooms[nr][nc] == INF
                ) {
                    rooms[nr][nc] = rooms[cur[0]][cur[1]] + 1; // first visit = nearest gate
                    q.add(new int[] { nr, nc });
                }
            }
        }
    }
}

