class Solution {

    public int ladderLength(
        String beginWord,
        String endWord,
        List<String> wordList
    ) {
        int n = wordList.size();
        boolean[] used = new boolean[n];
        Deque<String> q = new ArrayDeque<>();
        q.add(beginWord);
        int steps = 1;
        while (!q.isEmpty()) {
            for (int sz = q.size(); sz > 0; sz--) {
                String cur = q.poll();
                if (cur.equals(endWord)) return steps;
                for (int i = 0; i < n; i++) {
                    if (!used[i] && oneApart(cur, wordList.get(i))) {
                        // scan the whole list
                        used[i] = true;
                        q.add(wordList.get(i));
                    }
                }
            }
            steps++;
        }
        return 0;
    }

    private boolean oneApart(String a, String b) {
        int diff = 0;
        for (int i = 0; i < a.length(); i++) if (
            a.charAt(i) != b.charAt(i) && ++diff > 1
        ) return false;
        return diff == 1;
    }
}

