var ladderLength = function (beginWord, endWord, wordList) {
    const dict = new Set(wordList);
    if (!dict.has(endWord)) return 0;
    dict.delete(beginWord);
    const A = "a".charCodeAt(0);
    let level = [beginWord],
        steps = 1;
    while (level.length) {
        const next = [];
        for (const word of level) {
            const w = word.split("");
            for (let i = 0; i < w.length; i++) {
                const orig = w[i];
                for (let k = 0; k < 26; k++) {
                    const ch = String.fromCharCode(A + k);
                    if (ch === orig) continue;
                    w[i] = ch;
                    const cand = w.join("");
                    if (cand === endWord) return steps + 1;
                    if (dict.has(cand)) {
                        dict.delete(cand);
                        next.push(cand);
                    }
                }
                w[i] = orig;
            }
        }
        level = next;
        steps++;
    }
    return 0;
};

