class Solution {

    public int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int m = image.length,
            n = image[0].length,
            orig = image[sr][sc];
        boolean[][] filled = new boolean[m][n];
        filled[sr][sc] = true;
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) {
                if (filled[r][c] || image[r][c] != orig) continue;
                for (int[] d : dirs) {
                    int nr = r + d[0],
                        nc = c + d[1];
                    if (
                        nr >= 0 &&
                        nr < m &&
                        nc >= 0 &&
                        nc < n &&
                        filled[nr][nc]
                    ) {
                        filled[r][c] = true; // touches the filled area
                        changed = true;
                        break;
                    }
                }
            }
        }
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) if (
            filled[r][c]
        ) image[r][c] = color;
        return image;
    }
}

