var floodFill = function (image, sr, sc, color) {
    const m = image.length,
        n = image[0].length,
        orig = image[sr][sc];
    const filled = Array.from({ length: m }, () =>
        new Array(n).fill(false),
    );
    filled[sr][sc] = true;
    const dirs = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
    ];
    let changed = true;
    while (changed) {
        changed = false;
        for (let r = 0; r < m; r++)
            for (let c = 0; c < n; c++) {
                if (filled[r][c] || image[r][c] !== orig) continue;
                if (dirs.some(([dr, dc]) => filled[r + dr]?.[c + dc])) {
                    filled[r][c] = true;
                    changed = true;
                }
            }
    }
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (filled[r][c]) image[r][c] = color;
    return image;
};

