class Solution {

    public int[][] floodFill(int[][] image, int sr, int sc, int color) {
        int orig = image[sr][sc];
        if (orig != color) paint(image, sr, sc, orig, color); // same color would loop forever
        return image;
    }

    private void paint(int[][] img, int r, int c, int orig, int color) {
        if (
            r < 0 ||
            r >= img.length ||
            c < 0 ||
            c >= img[0].length ||
            img[r][c] != orig
        ) return;
        img[r][c] = color; // painting doubles as "visited"
        paint(img, r + 1, c, orig, color);

        paint(img, r - 1, c, orig, color);
        paint(img, r, c + 1, orig, color);
        paint(img, r, c - 1, orig, color);
    }
}

