var floodFill = function (image, sr, sc, color) {
    const orig = image[sr][sc];
    if (orig === color) return image;
    const m = image.length,
        n = image[0].length;
    const paint = (r, c) => {
        if (r < 0 || r >= m || c < 0 || c >= n || image[r][c] !== orig)
            return;
        image[r][c] = color;
        paint(r + 1, c);
        paint(r - 1, c);
        paint(r, c + 1);
        paint(r, c - 1);
    };
    paint(sr, sc);
    return image;
};

