class Solution {

    public int numIslands(char[][] grid) {
        int n = grid.length,
            m = grid[0].length,
            count = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != '1') continue;
                boolean[][] seen = new boolean[n][m];
                Deque<int[]> q = new ArrayDeque<>();
                q.add(new int[] { r, c });
                seen[r][c] = true;
                int minId = r * m + c;
                while (!q.isEmpty()) {
                    int[] cur = q.poll();
                    minId = Math.min(minId, cur[0] * m + cur[1]);
                    for (int dr = -1; dr <= 1; dr++) for (
                        int dc = -1;
                        dc <= 1;
                        dc++
                    ) {
                        int nr = cur[0] + dr,
                            nc = cur[1] + dc;
                        if (
                            nr >= 0 &&
                            nr < n &&
                            nc >= 0 &&
                            nc < m &&
                            grid[nr][nc] == '1' &&
                            !seen[nr][nc]
                        ) {
                            seen[nr][nc] = true;

                            q.add(new int[] { nr, nc });
                        }
                    }
                }
                if (minId == r * m + c) count++;
            }
        }
        return count;
    }
}

