class Solution {

    public int[][] nearest(int[][] grid) {
        int n = grid.length,
            m = grid[0].length;
        List<int[]> ones = new ArrayList<>();
        for (int r = 0; r < n; r++) for (int c = 0; c < m; c++) if (
            grid[r][c] == 1
        ) ones.add(new int[] { r, c });
        int[][] dist = new int[n][m];
        for (int r = 0; r < n; r++) for (int c = 0; c < m; c++) {
            int best = Integer.MAX_VALUE;
            for (int[] o : ones)
                best = Math.min(
                    best,
                    Math.abs(r - o[0]) + Math.abs(c - o[1])
                );
            dist[r][c] = best;
        }
        return dist;
    }
}

