function nearest(grid) {
    const n = grid.length,
        m = grid[0].length;
    const ones = [];
    for (let r = 0; r < n; r++)
        for (let c = 0; c < m; c++)
            if (grid[r][c] === 1) ones.push([r, c]);
    return grid.map((row, r) =>
        row.map((_, c) =>
            Math.min(
                ...ones.map(
                    ([or, oc]) => Math.abs(r - or) + Math.abs(c - oc),
                ),
            ),
        ),
    );
}

