class Solution {

    public int[][] nearest(int[][] grid) {
        int n = grid.length,
            m = grid[0].length;
        int[][] dist = new int[n][m];
        Deque<int[]> q = new ArrayDeque<>();
        for (int r = 0; r < n; r++) for (int c = 0; c < m; c++) {
            if (grid[r][c] == 1) {
                dist[r][c] = 0;
                q.add(new int[] { r, c });
            }
            // every 1 is a source
            else dist[r][c] = -1; // not reached yet
        }
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            for (int[] d : dirs) {
                int nr = cur[0] + d[0],
                    nc = cur[1] + d[1];
                if (
                    nr >= 0 &&
                    nr < n &&
                    nc >= 0 &&
                    nc < m &&
                    dist[nr][nc] == -1
                ) {
                    dist[nr][nc] = dist[cur[0]][cur[1]] + 1;
                    q.add(new int[] { nr, nc });
                }
            }
        }
        return dist;
    }
}

