class Solution {

    public int numDistinctIslands(int[][] grid) {
        int m = grid.length,
            n = grid[0].length;
        boolean[][] vis = new boolean[m][n];
        List<List<int[]>> shapes = new ArrayList<>();
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) {
            if (grid[r][c] != 1 || vis[r][c]) continue;
            List<int[]> cells = new ArrayList<>();
            collect(grid, vis, r, c, r, c, cells);
            cells.sort((a, b) ->
                a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]
            );
            boolean seen = false;
            for (List<int[]> s : shapes)
                if (same(s, cells)) {
                    seen = true;
                    break;
                } // pairwise compare
            if (!seen) shapes.add(cells);
        }

        return shapes.size();
    }

    private void collect(
        int[][] g,
        boolean[][] vis,
        int r,
        int c,
        int br,
        int bc,
        List<int[]> cells
    ) {
        if (
            r < 0 ||
            r >= g.length ||
            c < 0 ||
            c >= g[0].length ||
            g[r][c] != 1 ||
            vis[r][c]
        ) return;
        vis[r][c] = true;
        cells.add(new int[] { r - br, c - bc }); // relative to base cell
        collect(g, vis, r + 1, c, br, bc, cells);
        collect(g, vis, r - 1, c, br, bc, cells);
        collect(g, vis, r, c + 1, br, bc, cells);
        collect(g, vis, r, c - 1, br, bc, cells);
    }

    private boolean same(List<int[]> a, List<int[]> b) {
        if (a.size() != b.size()) return false;
        for (int i = 0; i < a.size(); i++) if (
            a.get(i)[0] != b.get(i)[0] || a.get(i)[1] != b.get(i)[1]
        ) return false;
        return true;
    }
}

