var numDistinctIslands = function (grid) {
    const m = grid.length,
        n = grid[0].length;
    const vis = Array.from({ length: m }, () =>
        new Array(n).fill(false),
    );
    const shapes = [];
    const collect = (r, c, br, bc, cells) => {
        if (
            r < 0 ||
            r >= m ||
            c < 0 ||
            c >= n ||
            grid[r][c] !== 1 ||
            vis[r][c]
        )
            return;
        vis[r][c] = true;
        cells.push([r - br, c - bc]);
        collect(r + 1, c, br, bc, cells);
        collect(r - 1, c, br, bc, cells);
        collect(r, c + 1, br, bc, cells);
        collect(r, c - 1, br, bc, cells);
    };
    const same = (a, b) =>
        a.length === b.length &&
        a.every((p, i) => p[0] === b[i][0] && p[1] === b[i][1]);
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++) {
            if (grid[r][c] !== 1 || vis[r][c]) continue;
            const cells = [];
            collect(r, c, r, c, cells);
            cells.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
            if (!shapes.some((s) => same(s, cells))) shapes.push(cells);
        }
    return shapes.length;
};

