class Solution {

    public int numDistinctIslands(int[][] grid) {
        int m = grid.length,
            n = grid[0].length;
        boolean[][] vis = new boolean[m][n];
        Set<String> shapes = new HashSet<>();
        for (int r = 0; r < m; r++) for (int c = 0; c < n; c++) if (
            grid[r][c] == 1 && !vis[r][c]
        ) {
            StringBuilder sig = new StringBuilder();
            dfs(grid, vis, r, c, r, c, sig); // base = first cell in scan order
            shapes.add(sig.toString());
        }
        return shapes.size();
    }

    private void dfs(
        int[][] g,
        boolean[][] vis,
        int r,
        int c,
        int br,
        int bc,
        StringBuilder sig
    ) {
        if (
            r < 0 ||
            r >= g.length ||
            c < 0 ||
            c >= g[0].length ||
            g[r][c] != 1 ||
            vis[r][c]
        ) return;
        vis[r][c] = true;
        sig.append(r - br)
            .append(',')
            .append(c - bc)
            .append(';'); // translation-invariant
        dfs(g, vis, r + 1, c, br, bc, sig); // fixed direction order => same shape, same string
        dfs(g, vis, r - 1, c, br, bc, sig);
        dfs(g, vis, r, c + 1, br, bc, sig);
        dfs(g, vis, r, c - 1, br, bc, sig);
    }
}

