var numDistinctIslands = function (grid) {
    const m = grid.length,
        n = grid[0].length;
    const vis = Array.from({ length: m }, () =>
        new Array(n).fill(false),
    );
    const shapes = new Set();
    const dfs = (r, c, br, bc, sig) => {
        if (
            r < 0 ||
            r >= m ||
            c < 0 ||
            c >= n ||
            grid[r][c] !== 1 ||
            vis[r][c]
        )
            return;
        vis[r][c] = true;
        sig.push(`${r - br},${c - bc}`);
        dfs(r + 1, c, br, bc, sig);
        dfs(r - 1, c, br, bc, sig);
        dfs(r, c + 1, br, bc, sig);
        dfs(r, c - 1, br, bc, sig);
    };
    for (let r = 0; r < m; r++)
        for (let c = 0; c < n; c++)
            if (grid[r][c] === 1 && !vis[r][c]) {
                const sig = [];
                dfs(r, c, r, c, sig);
                shapes.add(sig.join(";"));
            }
    return shapes.size;
};

