class Solution {

    public boolean isCycle(int V, ArrayList<ArrayList<Integer>> adj) {
        for (int u = 0; u < V; u++) for (int v : adj.get(u))
            if (u < v && reachableWithout(u, v, V, adj)) return true;
        return false;
    }

    // BFS from u to v, never using the direct edge u-v
    private boolean reachableWithout(
        int u,
        int v,
        int V,
        ArrayList<ArrayList<Integer>> adj
    ) {
        boolean[] seen = new boolean[V];
        Deque<Integer> q = new ArrayDeque<>();
        q.add(u);
        seen[u] = true;
        while (!q.isEmpty()) {
            int x = q.poll();
            for (int y : adj.get(x)) {
                if ((x == u && y == v) || (x == v && y == u)) continue; // skip the removed edge
                if (y == v) return true;

                if (!seen[y]) {
                    seen[y] = true;
                    q.add(y);
                }
            }
        }
        return false;
    }
}

