function isCycle(V, adj) {
    const reachableWithout = (u, v) => {
        const seen = new Array(V).fill(false);
        const q = [u];
        seen[u] = true;
        for (let i = 0; i < q.length; i++) {
            const x = q[i];
            for (const y of adj[x]) {
                if ((x === u && y === v) || (x === v && y === u))
                    continue; // removed edge
                if (y === v) return true;
                if (!seen[y]) {
                    seen[y] = true;
                    q.push(y);
                }
            }
        }
        return false;
    };
    for (let u = 0; u < V; u++)
        for (const v of adj[u])
            if (u < v && reachableWithout(u, v)) return true;
    return false;
}

