class Solution {

    public boolean isCycle(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] vis = new boolean[V];
        for (int i = 0; i < V; i++) if (
            !vis[i] && dfs(i, -1, adj, vis)
        ) return true; // every component
        return false;
    }

    private boolean dfs(
        int u,
        int parent,
        ArrayList<ArrayList<Integer>> adj,
        boolean[] vis
    ) {
        vis[u] = true;
        for (int v : adj.get(u)) {
            if (!vis[v]) {
                if (dfs(v, u, adj, vis)) return true;
            } else if (v != parent) {
                return true; // visited and not the edge we came from -> cycle
            }
        }
        return false;
    }
}

