function isCycle(V, adj) {
    const vis = new Array(V).fill(false);
    const dfs = (u, parent) => {
        vis[u] = true;
        for (const v of adj[u]) {
            if (!vis[v]) {
                if (dfs(v, u)) return true;
            } else if (v !== parent) {
                return true; // second path to v
            }
        }
        return false;
    };
    for (let i = 0; i < V; i++) if (!vis[i] && dfs(i, -1)) return true;
    return false;
}

