class Solution {

    public boolean isBipartite(int[][] graph) {
        int V = graph.length;
        for (long mask = 0; mask < 1L << V; mask++) {
            // bit i = color of node i
            boolean ok = true;
            for (int u = 0; u < V && ok; u++) for (int v : graph[u])
                if (((mask >> u) & 1) == ((mask >> v) & 1)) {
                    ok = false;
                    break;
                }
            if (ok) return true;
        }
        return false;
    }
}

