    const V = graph.length;
    for (let mask = 0; mask < 2 ** V; mask++) {
        const color = (i) => Math.floor(mask / 2 ** i) % 2; // works beyond 32 bits
        let ok = true;
        for (let u = 0; u < V && ok; u++)
            for (const v of graph[u])
                if (color(u) === color(v)) {
                    ok = false;
                    break;
                }
        if (ok) return true;
    }
    return false;
};

