class Solution {

    public boolean isBipartite(int[][] graph) {
        int V = graph.length;
        int[] color = new int[V];
        Arrays.fill(color, -1);
        for (int s = 0; s < V; s++) {
            if (color[s] != -1) continue;
            color[s] = 0; // new component
            Deque<Integer> q = new ArrayDeque<>();
            q.add(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : graph[u]) {
                    if (color[v] == -1) {
                        color[v] = 1 - color[u]; // forced opposite color
                        q.add(v);
                    } else if (color[v] == color[u]) {
                        return false; // odd cycle
                    }
                }
            }
        }
        return true;
    }
}

