class Solution {

    public boolean isCyclic(int V, ArrayList<ArrayList<Integer>> adj) {
        for (int s = 0; s < V; s++) {
            boolean[] seen = new boolean[V];
            Deque<Integer> q = new ArrayDeque<>();
            for (int v : adj.get(s))
                if (!seen[v]) {
                    seen[v] = true;
                    q.add(v);
                }
            while (!q.isEmpty()) {
                int u = q.poll();
                if (u == s) return true; // came back to the start
                for (int v : adj.get(u))
                    if (!seen[v]) {
                        seen[v] = true;
                        q.add(v);
                    }
            }
        }
        return false;
    }
}

