class Solution {

    public boolean isCyclic(int V, ArrayList<ArrayList<Integer>> adj) {
        int[] state = new int[V]; // 0 unvisited, 1 on path, 2 done
        for (int i = 0; i < V; i++) if (
            state[i] == 0 && dfs(i, adj, state)
        ) return true;
        return false;
    }

    private boolean dfs(
        int u,
        ArrayList<ArrayList<Integer>> adj,
        int[] state
    ) {
        state[u] = 1;
        for (int v : adj.get(u)) {
            if (state[v] == 1) return true; // back edge to an ancestor -> cycle
            if (state[v] == 0 && dfs(v, adj, state)) return true;
        }
        state[u] = 2; // fully explored, no cycle through here
        return false;
    }
}

