class Solution {

    public ArrayList<Integer> topoSort(
        int V,
        ArrayList<ArrayList<Integer>> adj
    ) {
        int[] indeg = new int[V];
        for (int u = 0; u < V; u++) for (int v : adj.get(u)) indeg[v]++;
        boolean[] used = new boolean[V];
        ArrayList<Integer> order = new ArrayList<>();
        for (int round = 0; round < V; round++) {
            int pick = -1;
            for (int u = 0; u < V; u++) if (!used[u] && indeg[u] == 0) {
                pick = u;
                break;
            } // linear scan
            if (pick == -1) break; // cycle: no ready node
            used[pick] = true;
            order.add(pick);
            for (int v : adj.get(pick)) indeg[v]--;
        }
        return order;
    }
}

