class Solution {

    public ArrayList<Integer> topoSort(
        int V,
        ArrayList<ArrayList<Integer>> adj
    ) {
        boolean[] vis = new boolean[V];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < V; i++) if (!vis[i]) dfs(
            i,
            adj,
            vis,
            stack
        );
        ArrayList<Integer> order = new ArrayList<>();
        while (!stack.isEmpty()) order.add(stack.pop());
        return order;
    }

    private void dfs(
        int u,
        ArrayList<ArrayList<Integer>> adj,
        boolean[] vis,
        Deque<Integer> stack
    ) {
        vis[u] = true;
        for (int v : adj.get(u)) if (!vis[v]) dfs(v, adj, vis, stack);
        stack.push(u); // pushed only after everything that depends on u
    }
}

