class Solution {

    public int kosaraju(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[][] reach = new boolean[V][V];
        for (int i = 0; i < V; i++) fill(i, adj, reach[i]); // reach[i][j]: i can reach j
        boolean[] assigned = new boolean[V];
        int count = 0;
        for (int i = 0; i < V; i++) {
            if (assigned[i]) continue;
            count++;
            for (int j = 0; j < V; j++) if (
                reach[i][j] && reach[j][i]
            ) assigned[j] = true; // mutually reachable
        }
        return count;
    }

    private void fill(
        int u,
        ArrayList<ArrayList<Integer>> adj,
        boolean[] seen
    ) {
        seen[u] = true;
        for (int v : adj.get(u)) if (!seen[v]) fill(v, adj, seen);
    }
}

