class Solution {

    public int kosaraju(int V, ArrayList<ArrayList<Integer>> adj) {
        boolean[] vis = new boolean[V];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < V; i++) if (!vis[i]) order(
            i,
            adj,
            vis,
            stack
        ); // pass 1: finish order

        List<List<Integer>> rev = new ArrayList<>(); // transpose graph
        for (int i = 0; i < V; i++) rev.add(new ArrayList<>());
        for (int u = 0; u < V; u++) for (int v : adj.get(u))
            rev.get(v).add(u);

        Arrays.fill(vis, false);
        int count = 0;
        while (!stack.isEmpty()) {
            // pass 2
            int u = stack.pop(); // latest finish first
            if (!vis[u]) {
                count++;
                mark(u, rev, vis);
            }
        }
        return count;
    }

    private void order(
        int u,
        ArrayList<ArrayList<Integer>> adj,
        boolean[] vis,
        Deque<Integer> stack
    ) {
        vis[u] = true;
        for (int v : adj.get(u)) if (!vis[v]) order(v, adj, vis, stack);
        stack.push(u);
    }

    private void mark(int u, List<List<Integer>> rev, boolean[] vis) {
        vis[u] = true; // stays inside one SCC
        for (int v : rev.get(u)) if (!vis[v]) mark(v, rev, vis);
    }
}

