function kosaraju(V, adj) {
    const vis = new Array(V).fill(false);
    const stack = [];
    const order = (u) => {
        vis[u] = true;
        for (const v of adj[u]) if (!vis[v]) order(v);
        stack.push(u); // finish time
    };
    for (let i = 0; i < V; i++) if (!vis[i]) order(i);

    const rev = Array.from({ length: V }, () => []);
    for (let u = 0; u < V; u++) for (const v of adj[u]) rev[v].push(u);

    vis.fill(false);
    const mark = (u) => {
        vis[u] = true;
        for (const v of rev[u]) if (!vis[v]) mark(v);
    };
    let count = 0;
    while (stack.length) {
        const u = stack.pop();
        if (!vis[u]) {
            count++;
            mark(u);
        }
    }
    return count;
}

