class Solution {

    public List<List<Integer>> criticalConnections(
        int n,
        List<List<Integer>> connections
    ) {
        List<List<int[]>> adj = new ArrayList<>(); // {neighbour, edgeId}
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < connections.size(); i++) {
            int a = connections.get(i).get(0),
                b = connections.get(i).get(1);
            adj.get(a).add(new int[] { b, i });
            adj.get(b).add(new int[] { a, i });
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < connections.size(); i++) {
            int u = connections.get(i).get(0),
                v = connections.get(i).get(1);
            boolean[] seen = new boolean[n];

            Deque<Integer> q = new ArrayDeque<>();
            q.add(u);
            seen[u] = true;
            while (!q.isEmpty()) {
                int x = q.poll();
                for (int[] e : adj.get(x)) {
                    if (e[1] == i || seen[e[0]]) continue; // pretend edge i is removed
                    seen[e[0]] = true;
                    q.add(e[0]);
                }
            }
            if (!seen[v]) res.add(Arrays.asList(u, v)); // v cut off -> bridge
        }
        return res;
    }
}

