        adj[b].push([a, i]);
    });
    const res = [];
    connections.forEach(([u, v], i) => {
        const seen = new Array(n).fill(false);
        const q = [u];
        seen[u] = true;
        for (let k = 0; k < q.length; k++) {
            for (const [y, id] of adj[q[k]]) {
                if (id === i || seen[y]) continue; // edge i removed
                seen[y] = true;
                q.push(y);
            }
        }
        if (!seen[v]) res.push([u, v]);
    });
    return res;
};

