class Solution {

    private List<List<Integer>> adj, res;

    private int[] tin, low;
    private int timer = 0;

    public List<List<Integer>> criticalConnections(
        int n,
        List<List<Integer>> connections
    ) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (List<Integer> c : connections) {
            adj.get(c.get(0)).add(c.get(1));
            adj.get(c.get(1)).add(c.get(0));
        }
        tin = new int[n];
        low = new int[n];
        Arrays.fill(tin, -1);
        res = new ArrayList<>();
        for (int i = 0; i < n; i++) if (tin[i] == -1) dfs(i, -1);
        return res;
    }

    private void dfs(int u, int parent) {
        tin[u] = low[u] = timer++;
        for (int v : adj.get(u)) {
            if (v == parent) continue; // don't use the tree edge backwards
            if (tin[v] == -1) {
                dfs(v, u);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > tin[u]) res.add(Arrays.asList(u, v)); // v's subtree can't get around u-v
            } else {
                low[u] = Math.min(low[u], tin[v]); // back edge
            }
        }
    }
}

