class Solution {

    public ArrayList<Integer> articulationPoints(
        int V,
        ArrayList<ArrayList<Integer>> adj
    ) {
        int base = components(V, adj, -1);
        ArrayList<Integer> res = new ArrayList<>();
        for (int x = 0; x < V; x++) if (
            components(V, adj, x) > base
        ) res.add(x); // removing x split something
        if (res.isEmpty()) res.add(-1);
        return res;
    }

    // number of components when vertex 'removed' is deleted (-1 = none)
    private int components(
        int V,
        ArrayList<ArrayList<Integer>> adj,
        int removed
    ) {
        boolean[] seen = new boolean[V];
        if (removed >= 0) seen[removed] = true;
        int count = 0;
        for (int s = 0; s < V; s++) {
            if (seen[s]) continue;
            count++;
            Deque<Integer> q = new ArrayDeque<>();
            q.add(s);
            seen[s] = true;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int v : adj.get(u))
                    if (!seen[v]) {
                        seen[v] = true;
                        q.add(v);
                    }
            }
        }
        return count;
    }
}

