        if (removed >= 0) seen[removed] = true;
        let count = 0;
        for (let s = 0; s < V; s++) {
            if (seen[s]) continue;
            count++;
            const q = [s];
            seen[s] = true;
            for (let i = 0; i < q.length; i++)
                for (const v of adj[q[i]])
                    if (!seen[v]) {
                        seen[v] = true;
                        q.push(v);
                    }
        }
        return count;
    };
    const base = components(-1);
    const res = [];
    for (let x = 0; x < V; x++) if (components(x) > base) res.push(x);
    return res.length ? res : [-1];
}

