class Solution {

    private int[] tin, low;
    private boolean[] isAP;
    private int timer = 0;

    public ArrayList<Integer> articulationPoints(
        int V,
        ArrayList<ArrayList<Integer>> adj
    ) {
        tin = new int[V];
        low = new int[V];
        isAP = new boolean[V];
        Arrays.fill(tin, -1);
        for (int i = 0; i < V; i++) if (tin[i] == -1) dfs(i, -1, adj);
        ArrayList<Integer> res = new ArrayList<>();
        for (int i = 0; i < V; i++) if (isAP[i]) res.add(i); // already sorted
        if (res.isEmpty()) res.add(-1);
        return res;
    }

    private void dfs(
        int u,
        int parent,
        ArrayList<ArrayList<Integer>> adj
    ) {
        tin[u] = low[u] = timer++;
        int children = 0;
        for (int v : adj.get(u)) {
            if (v == parent) continue;
            if (tin[v] == -1) {
                dfs(v, u, adj);
                low[u] = Math.min(low[u], low[v]);
                if (parent != -1 && low[v] >= tin[u]) isAP[u] = true; // v's subtree depends on u
                children++;
            } else {
                low[u] = Math.min(low[u], tin[v]); // back edge: use tin, not low
            }
        }
        if (parent == -1 && children > 1) isAP[u] = true; // root rule
    }
}

